using System;

namespace Tsumo.Tests
{
    public static class Node_modules_Tsumo_engine_src_diagnostics
    {
        public static TsumoError createTsumoError(string code, string message, string? file = null, double? line = null, double? column = null)
        {
            return new TsumoError(new TsumoDiagnostic(code, "error", message, file, line, column));
        }
        private static readonly System.Lazy<object?> __tsonic_module_initialization = new System.Lazy<object?>(() => __tsonic_module_init_core());
        private static object? __tsonic_module_init_core()
        {
            return null;
        }
        public static void __tsonic_module_init()
        {
            _ = __tsonic_module_initialization.Value;
        }
    }
    public class TsumoDiagnostic
    {
        public string code;
        public string category;
        public string message;
        public string? file;
        public double? line;
        public double? column;
        public TsumoDiagnostic(string code, string category, string message, string? file = null, double? line = null, double? column = null)
        {
            this.code = code;
            this.category = category;
            this.message = message;
            this.file = file;
            this.line = line;
            this.column = column;
        }
        public string format()
        {
            string location = this.file is null ? "" : this.line is null ? $"{this.file}: " : $"{this.file}:{this.line.Value}:{this.column ?? 1}: ";
            return $"{location}{this.code}: {this.message}";
        }
    }
    public class TsumoError : Tsonic.CSharp.Runtime.Error
    {
        public TsumoDiagnostic diagnostic;
        public TsumoError(TsumoDiagnostic diagnostic) : base(diagnostic.format())
        {
            this.name = "TsumoError";
            this.diagnostic = diagnostic;
        }
    }
}
